	"dataSources": {
		"ds_annotation_occupancy_spike": {
			"name": "Occupancy spikes",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"SPACE_OCCUPANCY\" | rename spaceOccupancy.peakPeopleCount as people, spaceOccupancy.space.capacity as capacity, spaceOccupancy.space.name as room | where isnotnull(capacity) AND capacity>0 AND isnotnull(people) AND people>0 | eval pct=round(people/capacity*100, 0) | where pct > 50 | eval label=room.\" — \".pct.\"% full\" | table _time label",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_building_occupancy": {
			"name": "KPI Rooms Occupied",
			"options": {
				"extend": "ds_occupancy_trend",
				"query": "| fields _time \"Rooms Occupied\""
			},
			"type": "ds.chain"
		},
		"ds_device_by_building": {
			"name": "Devices by Building",
			"options": {
				"extend": "ds_location_breakdown",
				"query": "| stats sum(\"Unique Devices\") as \"Unique Devices\" by Building"
			},
			"type": "ds.chain"
		},
		"ds_device_presence_trend": {
			"name": "Device Presence Trend",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_PRESENCE\" devicePresence.location.inferredLocationTypes{}=FLOOR | eval active='devicePresence.activeDevicesCount', floor='devicePresence.location.name', city='devicePresence.location.parent.parent.name' | bin _time span=1h | stats max(active) as active by _time, floor, city | timechart fixedrange=false span=1h sum(active) by city",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_devices_trend": {
			"name": "Connected Devices Trend",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_LOCATION_UPDATE\" | spath output=devMac path=deviceLocationUpdate.device.macAddress | timechart fixedrange=false dc(devMac) as \"Connected Devices\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_kpi_devices": {
			"name": "KPI Connected Devices",
			"options": {
				"extend": "ds_devices_trend",
				"query": "| fields _time \"Connected Devices\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_ssids": {
			"name": "KPI Active SSIDs",
			"options": {
				"extend": "ds_ssids_trend",
				"query": "| fields _time \"Active SSIDs\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_users": {
			"name": "Active Users",
			"options": {
				"extend": "ds_user_presence_total",
				"query": "| fields _time \"Active Users\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_webex_count": {
			"name": "KPI Webex Devices",
			"options": {
				"extend": "ds_webex_trend",
				"query": "| fields _time \"Webex Devices\""
			},
			"type": "ds.chain"
		},
		"ds_location_breakdown": {
			"name": "Building Resilience - ds_spaces_location_breakdown",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_LOCATION_UPDATE\" \n| spath output=devMac path=deviceLocationUpdate.device.macAddress \n| stats dc(devMac) as \"Unique Devices\", latest(deviceLocationUpdate.location.apCount) as \"AP Count\" by deviceLocationUpdate.location.parent.parent.name, deviceLocationUpdate.location.parent.name, deviceLocationUpdate.location.name \n| rename deviceLocationUpdate.location.parent.parent.name as Campus, deviceLocationUpdate.location.parent.name as Building, deviceLocationUpdate.location.name as Floor",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_occupancy_trend": {
			"name": "Rooms Occupied Trend",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"SPACE_OCCUPANCY\" | eval occupied=if('spaceOccupancy.peoplePresence'==\"true\", 1, 0) | timechart fixedrange=false avg(occupied) as pct | eval \"Rooms Occupied\"=round(pct*100, 2)",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_room_detail": {
			"name": "Building Resilience - ds_room_detail",
			"options": {
				"app": "splunk-cisco-dashboards",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				},
				"ref": "Building Resilience - ds_room_detail",
				"useSavedTimeRange": false
			},
			"type": "ds.savedSearch"
		},
		"ds_rooms": {
			"name": "Room Utilization by Building",
			"options": {
				"extend": "ds_room_detail",
				"query": "| eval occupied=if(Presence=\"Occupied\", 1, 0) \n| stats count as rooms_total, sum(occupied) as rooms_used by Building | rename rooms_total as \"Total Rooms\", rooms_used as \"Rooms Used\""
			},
			"type": "ds.chain"
		},
		"ds_ssid_clients": {
			"name": "Building Resilience - ds_ssid_clients",
			"options": {
				"app": "splunk-cisco-dashboards",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				},
				"ref": "Building Resilience - ds_ssid_clients",
				"useSavedTimeRange": false
			},
			"type": "ds.savedSearch"
		},
		"ds_ssid_trend": {
			"name": "SSID Client Trend",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_ASSOCIATION\" deviceAssociation.event=\"ASSOCIATE\" | eval ssid='deviceAssociation.ssid' | timechart fixedrange=false dc(deviceAssociation.device.macAddress) as clients by ssid",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_ssids_trend": {
			"name": "Active SSIDs Trend",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_ASSOCIATION\" | eval ssid='deviceAssociation.ssid', event='deviceAssociation.event' | search event=\"ASSOCIATE\" | timechart fixedrange=false dc(ssid) as \"Active SSIDs\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_user_presence_total": {
			"name": "User Presence Total",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"USER_PRESENCE\" userPresence.location.inferredLocationTypes{}=FLOOR | eval active='userPresence.activeUsersCount.totalUsers', floor='userPresence.location.name' | bin _time span=1h | stats max(active) as active by _time, floor | timechart fixedrange=false span=1h sum(active) as \"Active Users\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_user_presence_trend": {
			"name": "Building Resilience - ds_user_presence_trend",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"USER_PRESENCE\" userPresence.location.inferredLocationTypes{}=FLOOR | eval active='userPresence.activeUsersCount.totalUsers', floor='userPresence.location.name', city='userPresence.location.parent.parent.name' | bin _time span=1h | stats max(active) as active by _time, floor, city | timechart fixedrange=false span=1h sum(active) by city",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_webex_by_building": {
			"name": "Webex Devices by Building",
			"options": {
				"extend": "ds_webex_devices",
				"query": "| stats count by Building"
			},
			"type": "ds.chain"
		},
		"ds_webex_devices": {
			"name": "Building Resilience - ds_webex_devices",
			"options": {
				"app": "splunk-cisco-dashboards",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				},
				"ref": "Building Resilience - ds_webex_devices",
				"useSavedTimeRange": false
			},
			"type": "ds.savedSearch"
		},
		"ds_webex_people_trend": {
			"name": "Webex People Count Trend",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"WEBEX_TELEMETRY\" | eval people='webexTelemetryUpdate.telemetries{}.peopleCount', device='webexTelemetryUpdate.deviceInfo.serialNumber', location=coalesce('webexTelemetryUpdate.location.parent.name', 'webexTelemetryUpdate.location.name') | where isnotnull(people) AND people >= 0 AND isnotnull(location) | bin _time span=1h | stats max(people) as people by _time, device, location | timechart fixedrange=false span=1h sum(people) as \"People Detected\" by location",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_webex_trend": {
			"name": "Webex Devices Trend",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"WEBEX_TELEMETRY\" | timechart fixedrange=false dc(webexTelemetryUpdate.deviceInfo.serialNumber) as \"Webex Devices\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		}
	},
